alter table student_keys enable row level security;
    INSERT INTO a2._bootstrap_migrations(name, digest) VALUES ('0027_student_keys.sql', '06add5f8c5088c5780ab269e30f5d0967007a395f2893617f30b52518bcc60b3');
  END IF;
END;
