  IF EXISTS (SELECT 1 FROM a2._bootstrap_migrations WHERE name = '0030_quarter_grade_snapshot.sql' AND digest <> '5ea5124967196f4b8b09157801a0578130b3ca30034adf75f56904707d11d9f8') THEN
